using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using SonadaBeds.Web.Models;
namespace SonadaBeds.Web.Data;
public static class SeedData
{
 public static async Task Initialize(IServiceProvider sp){var db=sp.GetRequiredService<SonadaDbContext>(); await db.Database.EnsureCreatedAsync(); if(!await db.Categories.AnyAsync()){var beds=new Category{Name="Beds",Slug="beds",Description="Made-to-order upholstered beds"}; var mattresses=new Category{Name="Mattresses",Slug="mattresses"}; db.Categories.AddRange(beds,mattresses); db.Products.AddRange(new Product{Name="Sonada Signature Ottoman Bed",Slug="signature-ottoman-bed",BasePrice=699,ImageUrl="/images/bed-1.svg",Featured=true,Category=beds,Description="A refined upholstered ottoman bed with generous hidden storage."},new Product{Name="Sonada Grand Wing Bed",Slug="grand-wing-bed",BasePrice=799,ImageUrl="/images/bed-2.svg",Featured=true,Category=beds,Description="A statement winged headboard with made-to-order upholstery."},new Product{Name="Hybrid Luxe 4000 Mattress",Slug="hybrid-luxe-4000",BasePrice=399,ImageUrl="/images/mattress.svg",Featured=true,Category=mattresses,Description="Luxury pocket springs with a premium comfort layer."}); await db.SaveChangesAsync();} if(!await db.Coupons.AnyAsync()){db.Coupons.Add(new Coupon{Code="WELCOME10",PercentOff=10,MinimumSpend=500}); await db.SaveChangesAsync();} var rm=sp.GetRequiredService<RoleManager<IdentityRole>>(); foreach(var role in new[]{"Admin","Manager","Customer"}) if(!await rm.RoleExistsAsync(role)) await rm.CreateAsync(new IdentityRole(role)); var um=sp.GetRequiredService<UserManager<ApplicationUser>>(); var adminEmail=Environment.GetEnvironmentVariable("SONADA_ADMIN_EMAIL"); var adminPassword=Environment.GetEnvironmentVariable("SONADA_ADMIN_PASSWORD"); if(!string.IsNullOrWhiteSpace(adminEmail)&&!string.IsNullOrWhiteSpace(adminPassword)&&await um.FindByEmailAsync(adminEmail)==null){var admin=new ApplicationUser{UserName=adminEmail,Email=adminEmail,EmailConfirmed=true,FullName="Sonada Admin"}; var result=await um.CreateAsync(admin,adminPassword); if(result.Succeeded) await um.AddToRoleAsync(admin,"Admin");}}
}
